do $$
declare bad text;
begin
  select string_agg(x.name || ' (' || x.city || ')', ', ') into bad from _new_hotels_gb x
   where (select count(*) from public.cities c where c.country_code = 'GB' and c.name = x.city) <> 1;
  if bad is not null then raise exception 'hotel city does not resolve to exactly one GB row (run the migration first?): %', bad; end if;
  select string_agg(x.name, ', ') into bad from _new_hotels_gb x join public.hotels h on h.michelin_url = x.michelin_url;
  if bad is not null then raise exception 'hotel already present (michelin_url): %', bad; end if;
end $$;
insert into public.hotels (hotel_code, name, michelin_keys, city_id, country_code, address, location, michelin_url, website_url, phone)
select x.code, x.name, x.keys,
       (select c.id from public.cities c where c.country_code = 'GB' and c.name = x.city), 'GB',
       x.address, ST_SetSRID(ST_MakePoint(x.lon, x.lat), 4326)::geography,
       x.michelin_url, x.website_url, x.phone
  from _new_hotels_gb x;

-- 1c. current 2026 Key row for every UK Key hotel that lacks one (new rows above, and existing
--     GB hotels the August World's 50 Best import left without one; PE_REPORT.md finding 1)
insert into public.award_history (entity_type, entity_id, guide_year, award_type, award_value, is_current, announced_on)
select 'hotel', h.id, 2026, 'michelin_keys', h.michelin_keys, true, date '2026-09-18'
  from public.hotels h
 where h.hotel_code = any(array['hotel_762', 'hotel_818', 'hotel_819', 'hotel_766', 'hotel_767', 'hotel_764', 'hotel_769', 'hotel_820', 'hotel_770', 'hotel_821', 'hotel_822', 'hotel_823', 'hotel_824', 'hotel_825', 'hotel_826', 'hotel_827', 'hotel_828', 'hotel_829', 'hotel_830', 'hotel_831', 'hotel_832', 'hotel_833', 'hotel_834', 'hotel_835', 'hotel_836', 'hotel_837', 'hotel_838', 'hotel_839', 'hotel_840', 'hotel_841', 'hotel_842', 'hotel_843', 'hotel_844', 'hotel_845', 'hotel_786', 'hotel_846', 'hotel_847', 'hotel_848', 'hotel_849', 'hotel_850', 'hotel_851', 'hotel_852', 'hotel_853', 'hotel_854', 'hotel_855', 'hotel_856', 'hotel_857', 'hotel_858', 'hotel_859', 'hotel_860', 'hotel_861', 'hotel_862', 'hotel_863', 'hotel_864', 'hotel_865', 'hotel_866', 'hotel_867', 'hotel_868', 'hotel_869', 'hotel_870', 'hotel_871', 'hotel_872', 'hotel_873', 'hotel_874', 'hotel_875', 'hotel_876', 'hotel_877', 'hotel_878', 'hotel_879', 'hotel_880', 'hotel_881', 'hotel_882', 'hotel_883', 'hotel_884', 'hotel_885', 'hotel_886', 'hotel_887', 'hotel_888', 'hotel_889', 'hotel_890', 'hotel_891', 'hotel_892', 'hotel_893', 'hotel_894', 'hotel_895', 'hotel_896', 'hotel_897', 'hotel_898', 'hotel_899', 'hotel_900', 'hotel_901', 'hotel_902', 'hotel_765', 'hotel_903', 'hotel_904', 'hotel_905', 'hotel_906', 'hotel_907', 'hotel_908', 'hotel_909', 'hotel_910', 'hotel_911', 'hotel_912', 'hotel_913', 'hotel_914', 'hotel_915', 'hotel_916', 'hotel_917', 'hotel_918', 'hotel_919', 'hotel_920', 'hotel_921', 'hotel_922', 'hotel_768', 'hotel_923', 'hotel_924', 'hotel_925', 'hotel_926', 'hotel_927', 'hotel_928', 'hotel_929', 'hotel_930', 'hotel_931', 'hotel_932', 'hotel_933', 'hotel_934', 'hotel_935', 'hotel_936', 'hotel_937'])
   and not exists (select 1 from public.award_history a where a.entity_type = 'hotel' and a.entity_id = h.id
                    and a.award_type = 'michelin_keys' and a.is_current);

-- 1d. existing GB hotels, fill-only (never overwrites)
create temp table _hfill_gb (code text primary key, phone text, website_url text) on commit drop;
insert into _hfill_gb values
    ('hotel_769', '+44 1963 577777', NULL),
    ('hotel_770', '+44 20 7836 4343', NULL),
    ('hotel_765', '+44 20 3906 1600', NULL);
update public.hotels h set phone = f.phone, updated_at = now() from _hfill_gb f where h.hotel_code = f.code and f.phone is not null and h.phone is null;
update public.hotels h set website_url = f.website_url, updated_at = now() from _hfill_gb f where h.hotel_code = f.code and f.website_url is not null and h.website_url is null;

