do $$
declare bad text;
begin
  select string_agg(x.code, ', ') into bad from _new_gb x join public.restaurants r on r.restaurant_code = x.code;
  if bad is not null then raise exception 'codes no longer free: %', bad; end if;
  select string_agg(x.name || ' (' || x.city || ')', ', ') into bad from _new_gb x
   where (select count(*) from public.cities c where c.country_code = 'GB' and c.name = x.city) <> 1;
  if bad is not null then raise exception 'city does not resolve to exactly one GB row (run the migration first?): %', bad; end if;
  select string_agg(x.name, ', ') into bad from _new_gb x join public.restaurants r on r.michelin_url = x.michelin_url;
  if bad is not null then raise exception 'already present (michelin_url): %', bad; end if;
end $$;
insert into public.restaurants (restaurant_code, name, michelin_stars, inclusion_reason, city_id, country_code,
                                address, location, michelin_url, website_url, phone, property_name, google_place_id)
select x.code, x.name, x.stars, 'michelin_star',
       (select c.id from public.cities c where c.country_code = 'GB' and c.name = x.city), 'GB',
       x.address, ST_SetSRID(ST_MakePoint(x.lon, x.lat), 4326)::geography,
       x.michelin_url, x.website_url, x.phone, x.property_name, x.place_id
  from _new_gb x;
insert into public.award_history (entity_type, entity_id, guide_year, award_type, award_value, is_current, announced_on)
select 'restaurant', r.id, 2026, 'michelin_stars', x.stars, true, date '2026-02-09'
  from _new_gb x join public.restaurants r on r.restaurant_code = x.code;

-- 5. existing restaurants, fill-only (never overwrites)
create temp table _fill_gb (code text primary key, phone text, website_url text, property_name text) on commit drop;
insert into _fill_gb values
    ('rest_0004', '+44 20 7629 8866', NULL, NULL),
    ('rest_0305', NULL, 'https://ikoyilondon.com/', NULL),
    ('rest_0329', NULL, 'https://kolrestaurant.com/', NULL);
update public.restaurants r set phone = f.phone, updated_at = now() from _fill_gb f where r.restaurant_code = f.code and f.phone is not null and r.phone is null;
update public.restaurants r set website_url = f.website_url, updated_at = now() from _fill_gb f where r.restaurant_code = f.code and f.website_url is not null and r.website_url is null;
update public.restaurants r set property_name = f.property_name, updated_at = now() from _fill_gb f where r.restaurant_code = f.code and f.property_name is not null and r.property_name is null
   and not exists (select 1 from public.hotel_restaurants hr where hr.restaurant_id = r.id);

