do $$
declare n int;
begin
  select count(*) into n from _links_gb l
   where not exists (select 1 from public.hotels h where h.hotel_code = l.hotel_code)
      or not exists (select 1 from public.restaurants r where r.restaurant_code = l.restaurant_code);
  if n <> 0 then raise exception '% links point at a missing hotel or restaurant', n; end if;
end $$;
insert into public.hotel_restaurants (hotel_id, restaurant_id, link_confidence, evidence, verified_at)
select h.id, r.id, l.confidence, l.evidence, now()
  from _links_gb l join public.hotels h on h.hotel_code = l.hotel_code join public.restaurants r on r.restaurant_code = l.restaurant_code
on conflict (hotel_id, restaurant_id) do nothing;

-- post-conditions: MICHELIN's live 2026 UK listing (Channel Islands excluded) and the 2026 UK Keys
do $$
declare n int;
begin
  select count(*) into n from public.restaurants where country_code = 'GB' and michelin_stars = 3;
  if n <> 10 then raise exception 'expected 10 three-star, found %', n; end if;
  select count(*) into n from public.restaurants where country_code = 'GB' and michelin_stars = 2;
  if n <> 23 then raise exception 'expected 23 two-star, found %', n; end if;
  select count(*) into n from public.restaurants where country_code = 'GB' and michelin_stars = 1;
  if n <> 163 then raise exception 'expected 163 one-star, found %', n; end if;
  select count(*) into n from public.restaurants r where r.country_code = 'GB'
     and (select count(*) from public.award_history ah where ah.entity_type = 'restaurant' and ah.entity_id = r.id
           and ah.award_type = 'michelin_stars' and ah.is_current) <> 1;
  if n <> 0 then raise exception '% restaurants without exactly one current star row', n; end if;
  select count(*) into n from public.restaurants r join public.award_history ah on ah.entity_type = 'restaurant'
     and ah.entity_id = r.id and ah.award_type = 'michelin_stars' and ah.is_current
   where r.country_code = 'GB' and ah.award_value is distinct from r.michelin_stars;
  if n <> 0 then raise exception '% restaurants disagree with their current award row', n; end if;
  select count(*) into n from public.restaurants r where r.country_code = 'GB' and r.property_name is not null
     and exists (select 1 from public.hotel_restaurants hr where hr.restaurant_id = r.id);
  if n <> 0 then raise exception '% restaurants have both a hotel link and a property_name', n; end if;
  -- Keys: the 129 UK Key hotels, plus the 1 hotel(s) still holding a Key MICHELIN no longer shows (left for a decision)
  select count(*) into n from public.hotels where country_code = 'GB' and michelin_keys = 3 and hotel_code <> all(array['hotel_763']);
  if n <> 9 then raise exception 'expected 9 three-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels where country_code = 'GB' and michelin_keys = 2 and hotel_code <> all(array['hotel_763']);
  if n <> 42 then raise exception 'expected 42 two-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels where country_code = 'GB' and michelin_keys = 1 and hotel_code <> all(array['hotel_763']);
  if n <> 78 then raise exception 'expected 78 one-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels h where h.country_code = 'GB' and h.michelin_keys is not null and h.hotel_code <> all(array['hotel_763'])
     and (select count(*) from public.award_history a where a.entity_type = 'hotel' and a.entity_id = h.id
           and a.award_type = 'michelin_keys' and a.is_current and a.award_value = h.michelin_keys) <> 1;
  if n <> 0 then raise exception '% Key hotels without exactly one matching current Key row', n; end if;
end $$;

-- ============================================================
-- IE
-- ============================================================

do $$
declare n int;
begin
  select count(*) into n from public.restaurants where country_code = 'IE';
  if n <> 0 then raise exception 'IE: expected 0 restaurants (export), found % -- production changed, re-check', n; end if;
  select count(*) into n from public.hotels where country_code = 'IE';
  if n <> 0 then raise exception 'IE: expected 0 hotels (export), found % -- production changed, re-check', n; end if;
  if exists (select 1 from public.restaurants where restaurant_code ~ '^rest_[0-9]+$'
              and substring(restaurant_code from 6)::int between 2636 and 2658) then
    raise exception 'restaurant codes rest_2636..rest_2658 are no longer free -- re-check';
  end if;
  if exists (select 1 from public.hotels where hotel_code ~ '^hotel_[0-9]+$'
              and substring(hotel_code from 7)::int between 938 and 956) then
    raise exception 'hotel codes hotel_938..hotel_956 are no longer free -- re-check';
  end if;
  if (select count(distinct guide_year) from public.award_history where award_type = 'michelin_keys' and is_current) > 1
     or exists (select 1 from public.award_history where award_type = 'michelin_keys' and is_current and guide_year <> 2026) then
    raise exception 'current michelin_keys rows are not all guide_year 2026 -- decide the year explicitly';
  end if;
end $$;

