do $$
declare bad text;
begin
  select string_agg(x.name || ' (' || x.city || ')', ', ') into bad from _new_hotels_ie x
   where (select count(*) from public.cities c where c.country_code = 'IE' and c.name = x.city) <> 1;
  if bad is not null then raise exception 'hotel city does not resolve to exactly one IE row (run the migration first?): %', bad; end if;
  select string_agg(x.name, ', ') into bad from _new_hotels_ie x join public.hotels h on h.michelin_url = x.michelin_url;
  if bad is not null then raise exception 'hotel already present (michelin_url): %', bad; end if;
end $$;
insert into public.hotels (hotel_code, name, michelin_keys, city_id, country_code, address, location, michelin_url, website_url, phone)
select x.code, x.name, x.keys,
       (select c.id from public.cities c where c.country_code = 'IE' and c.name = x.city), 'IE',
       x.address, ST_SetSRID(ST_MakePoint(x.lon, x.lat), 4326)::geography,
       x.michelin_url, x.website_url, x.phone
  from _new_hotels_ie x;

-- 1c. current 2026 Key row for every UK Key hotel that lacks one (new rows above, and existing
--     GB hotels the August World's 50 Best import left without one; PE_REPORT.md finding 1)
insert into public.award_history (entity_type, entity_id, guide_year, award_type, award_value, is_current, announced_on)
select 'hotel', h.id, 2026, 'michelin_keys', h.michelin_keys, true, date '2026-09-18'
  from public.hotels h
 where h.hotel_code = any(array['hotel_938', 'hotel_939', 'hotel_940', 'hotel_941', 'hotel_942', 'hotel_943', 'hotel_944', 'hotel_945', 'hotel_946', 'hotel_947', 'hotel_948', 'hotel_949', 'hotel_950', 'hotel_951', 'hotel_952', 'hotel_953', 'hotel_954', 'hotel_955', 'hotel_956'])
   and not exists (select 1 from public.award_history a where a.entity_type = 'hotel' and a.entity_id = h.id
                    and a.award_type = 'michelin_keys' and a.is_current);

