    ('rest_2655', 'The Morrison Room', 1::smallint, 'Maynooth', 'Carton House, Carton Demesne, Maynooth W23 TD98', -6.5675043, 53.3905215, 'https://guide.michelin.com/en/kildare/maynooth/restaurant/the-morrison-room', 'https://www.cartonhouse.com/dining/the-morrison-room', NULL, 'Carton House, A Fairmont Managed Hotel', NULL),
    ('rest_2656', 'The Oak Room', 1::smallint, 'Adare', 'Adare Manor, Adare V94 W8WR', -8.7772396, 52.5636528, 'https://guide.michelin.com/en/limerick/adare/restaurant/the-oak-room', 'https://www.adaremanor.com/dining/the-oak-room/', '+353 61 605 200', NULL, NULL),
    ('rest_2657', 'The Pullman', 1::smallint, 'Galway', 'Glenlo Abbey Hotel & Estate, Bushypark, Galway H91 XD8K', -9.0982813, 53.3007601, 'https://guide.michelin.com/en/galway/galway/restaurant/the-pullman', 'https://www.glenloabbeyhotel.ie/the-pullman.html', '+353 91 519 600', NULL, NULL),
    ('rest_2658', 'Variety Jones', 1::smallint, 'Dublin', '79 Thomas Street, Dublin D08 F2RN', -6.2761907, 53.3429574, 'https://guide.michelin.com/en/dublin/dublin/restaurant/variety-jones', 'https://www.varietyjones.ie/', '+353 1 567 1164', NULL, NULL);
do $$
declare bad text;
begin
  select string_agg(x.code, ', ') into bad from _new_ie x join public.restaurants r on r.restaurant_code = x.code;
  if bad is not null then raise exception 'codes no longer free: %', bad; end if;
  select string_agg(x.name || ' (' || x.city || ')', ', ') into bad from _new_ie x
   where (select count(*) from public.cities c where c.country_code = 'IE' and c.name = x.city) <> 1;
  if bad is not null then raise exception 'city does not resolve to exactly one IE row (run the migration first?): %', bad; end if;
  select string_agg(x.name, ', ') into bad from _new_ie x join public.restaurants r on r.michelin_url = x.michelin_url;
  if bad is not null then raise exception 'already present (michelin_url): %', bad; end if;
end $$;
insert into public.restaurants (restaurant_code, name, michelin_stars, inclusion_reason, city_id, country_code,
                                address, location, michelin_url, website_url, phone, property_name, google_place_id)
select x.code, x.name, x.stars, 'michelin_star',
       (select c.id from public.cities c where c.country_code = 'IE' and c.name = x.city), 'IE',
       x.address, ST_SetSRID(ST_MakePoint(x.lon, x.lat), 4326)::geography,
       x.michelin_url, x.website_url, x.phone, x.property_name, x.place_id
  from _new_ie x;
insert into public.award_history (entity_type, entity_id, guide_year, award_type, award_value, is_current, announced_on)
select 'restaurant', r.id, 2026, 'michelin_stars', x.stars, true, date '2026-02-09'
  from _new_ie x join public.restaurants r on r.restaurant_code = x.code;

-- 6. links to hotels in `hotels`
create temp table _links_ie (hotel_code text, restaurant_code text, confidence text, evidence text) on commit drop;
insert into _links_ie values
    ('hotel_939', 'rest_2637', 'exact', 'MICHELIN ''Every MICHELIN-Star Restaurant in Great Britain & Ireland 2026'': ''(Inside the ...-MICHELIN-Key Ballyfin Demesne)''; the hotel row''s pin (gb/ie_key_hotels_2026.csv) 67 m from the restaurant''s. 2026-10-29.'),
    ('hotel_952', 'rest_2646', 'exact', 'MICHELIN ''Every MICHELIN-Star Restaurant in Great Britain & Ireland 2026'': ''(Inside the ...-MICHELIN-Key Fitzwilliam Hotel Dublin)''; the hotel row''s pin (gb/ie_key_hotels_2026.csv) 7 m from the restaurant''s. 2026-10-29.'),
    ('hotel_944', 'rest_2652', 'exact', 'MICHELIN restaurant page ''Stay at the hotel'' -> https://guide.michelin.com/en/hotels-stays/dublin/the-merrion-5739 (The Merrion), a 2-Key hotel; restaurant pin 5 m from the hotel''s MICHELIN pin. 2026-10-29.'),
    ('hotel_945', 'rest_2653', 'campus', 'MICHELIN restaurant page ''Stay at the hotel'' -> https://guide.michelin.com/en/hotels-stays/county-cork/castlemartyr-resort-11433 (Castlemartyr Resort), a 1-Key hotel; restaurant pin 251 m from the hotel''s MICHELIN pin. 2026-10-29.'),
    ('hotel_941', 'rest_2654', 'exact', 'MICHELIN ''Every MICHELIN-Star Restaurant in Great Britain & Ireland 2026'': ''(Inside the ...-MICHELIN-Key Cashel Palace)''; the hotel row''s pin (gb/ie_key_hotels_2026.csv) 34 m from the restaurant''s. 2026-10-29.'),
    ('hotel_938', 'rest_2656', 'campus', 'MICHELIN ''Every MICHELIN-Star Restaurant in Great Britain & Ireland 2026'': ''(Inside the ...-MICHELIN-Key Adare Manor)''; the hotel row''s pin (gb/ie_key_hotels_2026.csv) 115 m from the restaurant''s. 2026-10-29.'),
    ('hotel_948', 'rest_2657', 'exact', 'MICHELIN ''Every MICHELIN-Star Restaurant in Great Britain & Ireland 2026'': ''(Inside the ...-MICHELIN-Key Glenlo Abbey Hotel)''; the hotel row''s pin (gb/ie_key_hotels_2026.csv) 41 m from the restaurant''s. 2026-10-29.');
do $$
declare n int;
begin
  select count(*) into n from _links_ie l
   where not exists (select 1 from public.hotels h where h.hotel_code = l.hotel_code)
      or not exists (select 1 from public.restaurants r where r.restaurant_code = l.restaurant_code);
  if n <> 0 then raise exception '% links point at a missing hotel or restaurant', n; end if;
end $$;
insert into public.hotel_restaurants (hotel_id, restaurant_id, link_confidence, evidence, verified_at)
select h.id, r.id, l.confidence, l.evidence, now()
  from _links_ie l join public.hotels h on h.hotel_code = l.hotel_code join public.restaurants r on r.restaurant_code = l.restaurant_code
on conflict (hotel_id, restaurant_id) do nothing;

-- post-conditions: MICHELIN's live 2026 UK listing (Channel Islands excluded) and the 2026 UK Keys
do $$
declare n int;
begin
  select count(*) into n from public.restaurants where country_code = 'IE' and michelin_stars = 3;
  if n <> 0 then raise exception 'expected 0 three-star, found %', n; end if;
  select count(*) into n from public.restaurants where country_code = 'IE' and michelin_stars = 2;
  if n <> 5 then raise exception 'expected 5 two-star, found %', n; end if;
  select count(*) into n from public.restaurants where country_code = 'IE' and michelin_stars = 1;
  if n <> 18 then raise exception 'expected 18 one-star, found %', n; end if;
  select count(*) into n from public.restaurants r where r.country_code = 'IE'
     and (select count(*) from public.award_history ah where ah.entity_type = 'restaurant' and ah.entity_id = r.id
           and ah.award_type = 'michelin_stars' and ah.is_current) <> 1;
  if n <> 0 then raise exception '% restaurants without exactly one current star row', n; end if;
  select count(*) into n from public.restaurants r join public.award_history ah on ah.entity_type = 'restaurant'
     and ah.entity_id = r.id and ah.award_type = 'michelin_stars' and ah.is_current
   where r.country_code = 'IE' and ah.award_value is distinct from r.michelin_stars;
  if n <> 0 then raise exception '% restaurants disagree with their current award row', n; end if;
  select count(*) into n from public.restaurants r where r.country_code = 'IE' and r.property_name is not null
     and exists (select 1 from public.hotel_restaurants hr where hr.restaurant_id = r.id);
  if n <> 0 then raise exception '% restaurants have both a hotel link and a property_name', n; end if;
  -- Keys: the 19 UK Key hotels, plus the 0 hotel(s) still holding a Key MICHELIN no longer shows (left for a decision)
  select count(*) into n from public.hotels where country_code = 'IE' and michelin_keys = 3;
  if n <> 2 then raise exception 'expected 2 three-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels where country_code = 'IE' and michelin_keys = 2;
  if n <> 5 then raise exception 'expected 5 two-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels where country_code = 'IE' and michelin_keys = 1;
  if n <> 12 then raise exception 'expected 12 one-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels h where h.country_code = 'IE' and h.michelin_keys is not null
     and (select count(*) from public.award_history a where a.entity_type = 'hotel' and a.entity_id = h.id
           and a.award_type = 'michelin_keys' and a.is_current and a.award_value = h.michelin_keys) <> 1;
  if n <> 0 then raise exception '% Key hotels without exactly one matching current Key row', n; end if;
end $$;

commit;


